public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }

    // Check if the file is a directory and recursively delete sub-directories
    if (file.isDirectory()) {
        FileUtils.deleteDirectory(file);
    } else {
        // Trigger the delete operation
        file.delete();
    }

    // Register a shutdown hook to ensure the file is deleted on JVM exit
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        if (file.exists()) {
            try {
                FileUtils.deleteDirectory(file);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }));
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File cannot be null");
    }

    if (file.isDirectory()) {
        FileUtils.deleteDirectory(file);
    } else {
        FileUtils.delete(file);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File cannot be null");
    }

    // Use a stack to create a depth-first search order of the files to delete
    Stack<File> stack = new Stack<>();
    stack.push(file);

    while (!stack.isEmpty()) {
        File currentFile = stack.pop();
        if (!currentFile.delete()) {
            throw new IOException("Failed to delete file: " + currentFile.getAbsolutePath());
        }

        // Check if the file is a directory
        Path path = Paths.get(currentFile.getAbsolutePath());
        if (Files.isDirectory(path)) {
            // Add all subdirectories to the stack for deletion later
            Files.list(path).forEach(stack::add);
        }
    }
}

