public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Create a deep copy of the graph to maintain immutability
    Graph<V,E> copiedGraph = new Graph<>(graph);

    // Create a mapping from vertex to itself
    Map<V,V> identityMapping = new HashMap<>(graph.size());
    for (V vertex : copiedGraph) {
        identityMapping.put(vertex, vertex);
    }

    // Return the identity mapping
    return new IsomorphicGraphMapping<>(identityMapping);
}

