public static String unescapeJava(String str) throws Exception {
    if (str == null || str.isEmpty()) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < str.length()) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 < str.length()) {
                char nextCh = str.charAt(i + 1);
                switch (nextCh) {
                    case 'n':
                        result.append('\n');
                        i += 2;
                        break;
                    case 't':
                        result.append('\t');
                        i += 2;
                        break;
                    case '"':
                        result.append('"');
                        i += 2;
                        break;
                    case '\\':
                        result.append('\\');
                        i += 2;
                        break;
                    default:
                        result.append(ch);
                        i += 1;
                        break;
                }
            } else {
                throw new Exception("Unfinished escape sequence found.");
            }
        } else {
            result.append(ch);
            i++;
        }
    }

    return result.toString();
}

