    }

    // Remove consecutive slashes
    while (newPath.startsWith("//")) {
        newPath = newPath.substring(2);
    }

    // Remove leading slash from the path
    if (newPath.startsWith("/")) {
        newPath = newPath.substring(1);
    }

    // Return the fully qualified file path
    return newPath;
}

