    pane.scrollRectangleToVisible(table.getCellRect(row, 0, false));

    // Delay repaint to ensure the table is painted properly
    try {
        Thread.sleep(100); // Adjust the delay as needed
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }

    // Repaint the table to show the newly selected row
    table.repaint();
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Invalid input arguments");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row number");
    }

    try {
        int previousRow = table.getSelectedRow();
        table.setRowSelectionInterval(row, row);
        table.repaint();

        if (previousRow != -1 && previousRow != row) {
            // Adjust the scroll position if necessary
            JScrollPane.JScrollBar verticalScrollBar = pane.getVerticalScrollBar();
            verticalScrollBar.setValue(table.getRowHeight() * (previousRow - row));
        }
    } catch (Exception e) {
        // Handle any errors that may occur during the method execution
        e.printStackTrace();
    }
}

