/**
 * Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
 * @param start the start time of the time range
 * @param end the end time of the time range
 * @return a list of time ranges
 */
protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    if (start < 0 || end <= 0) {
        throw new IllegalArgumentException("Start and end times must be positive values.");
    }

    long startTime = start;
